import pty, os, time, re, struct, fcntl, termios, select

def get_lesson_once(args, timeout=1.0):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 40, 150, 0, 0))
    pid = os.fork()
    if pid == 0:
        os.close(master)
        os.setsid()
        os.dup2(slave, 0)
        os.dup2(slave, 1)
        os.dup2(slave, 2)
        os.close(slave)
        os.execvp("./executable", ["./executable"] + args)
    else:
        os.close(slave)
        flags = fcntl.fcntl(master, fcntl.F_GETFL)
        fcntl.fcntl(master, fcntl.F_SETFL, flags | os.O_NONBLOCK)
        output = b""
        start = time.time()
        lesson = None
        # Poll for lesson
        while time.time() - start < timeout:
            time.sleep(0.05)
            try:
                while True:
                    try:
                        data = os.read(master, 8192)
                        if data:
                            output += data
                        else:
                            break
                    except BlockingIOError:
                        break
                    except OSError:
                        break
            except: pass
            # Try to extract lesson: look for pattern \x1b[7;\d+H\x1b[1m... 
            # Actually lesson at row 7 (1-indexed). In raw, we saw \x1b[7;31H\x1b[1m<lesson>
            # Let's decode and search
            try:
                text = output.decode('utf-8', errors='ignore')
                # Find all occurrences of \x1b[7;
                # Simpler: find \x1b[1m<lesson> where lesson is like "xx xx ..." ?
                # The lesson line has bold, then lesson + space, then escape.
                # Let's look for regex: \x1b\[1m([a-zA-Z ,\.]+?)(?:\x1b|\s*\x1b)
                # Actually lesson contains only letters, spaces. Let's try.
                # The title also has \x1b[1m ... ngrrram! ... So need to distinguish: title at row2, lesson at row7.
                # We can split by \x1b[7;
                if '\x1b[7;' in text:
                    # Get segment after last \x1b[7;
                    parts = text.split('\x1b[7;')
                    last = parts[-1]
                    # last starts like "31H\x1b[1mne io ...\x1b[..."
                    m = re.search(r'\x1b\[1m([A-Za-z ,\x00-\x7F]+?)\x1b', last)
                    if m:
                        cand = m.group(1).strip()
                        # Filter: should contain spaces and be reasonable length, not title
                        if ' ' in cand and 'ngrrram' not in cand and len(cand) > 3:
                            lesson = cand
                            break
            except Exception as e:
                pass
        # Quit
        try:
            os.write(master, b"\x1b")
            time.sleep(0.15)
        except: pass
        try:
            os.close(master)
        except: pass
        try:
            os.kill(pid, 9)
        except: pass
        try:
            os.waitpid(pid, 0)
        except: pass
        return lesson, time.time()-start

for args in [[], ["-n","3"], ["-n","w"], ["-n","2","-t","5","-c","10"]]:
    lesson, dur = get_lesson_once(args)
    print(f"args={args} => [{lesson}] in {dur:.2f}s")
