use clap::{Arg, Command, value_parser};

fn cli() -> Command {
    Command::new("executable")
        .disable_version_flag(true)
        .arg(Arg::new("n").short('n').long("n").default_value("2").value_name("2|3|4|w|file").help("use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file."))
        .arg(Arg::new("top").short('t').long("top").default_value("50").value_name("1-200").value_parser(value_parser!(i32)).help("use the top X ngrams ordered by usage."))
        .arg(Arg::new("combi").short('c').long("combi").default_value("2").value_name("1-200").value_parser(value_parser!(i32)).help("how many different ngrams to use in a single lesson."))
        .arg(Arg::new("rep").short('r').long("rep").default_value("3").value_name("number").value_parser(value_parser!(i32)).help("how often to repeat *each* different ngram in a lesson."))
        .arg(Arg::new("wpm").short('w').long("wpm").default_value("40").value_name("number").value_parser(value_parser!(i32)).help("the wpm threshold at which the lesson is considered a success."))
        .arg(Arg::new("acc").short('a').long("acc").default_value("94").value_name("0-100").value_parser(value_parser!(i32)).help("the accuracy in percent at which the lesson is considered a success."))
        .arg(Arg::new("emu-in").long("emu-in").default_value("").value_name("layout").hide_default_value(true).help("your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts. [default: ]"))
        .arg(Arg::new("emu-out").long("emu-out").default_value("").value_name("layout").hide_default_value(true).help("the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts. [default: ]"))
        .arg(Arg::new("show-ortho").long("show-ortho").action(clap::ArgAction::SetTrue).help("show keyboard in ortholinear format"))
        .arg(Arg::new("nokb").long("nokb").action(clap::ArgAction::SetTrue).help("pass this flag to disable the keyboard layout display."))
        .arg(Arg::new("cat").long("cat").action(clap::ArgAction::SetTrue).help("the most important flag. don't practice alone."))
}

fn main() {
    let m = match cli().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            let mut s = e.to_string();
            // Fix usage for tip cases to match original (all-args long usage)
            if s.contains("tip:") {
                // Find Usage line and replace
                let lines: Vec<String> = s.lines().map(|l| l.to_string()).collect();
                let mut out_lines: Vec<String> = Vec::new();
                for line in lines {
                    if line.starts_with("Usage: ") {
                        // Extract bin name (second word)
                        let bin = line.split_whitespace().nth(1).unwrap_or("executable");
                        out_lines.push(format!("Usage: {} <--n <2|3|4|w|file>|--top <1-200>|--combi <1-200>|--rep <number>|--wpm <number>|--acc <0-100>|--emu-in <layout>|--emu-out <layout>|--show-ortho|--nokb|--cat>", bin));
                    } else {
                        out_lines.push(line);
                    }
                }
                s = out_lines.join("\n") + "\n";
                eprint!("{}", s);
                std::process::exit(2);
            } else {
                e.exit();
            }
        }
    };
    println!("ok top={}", m.get_one::<i32>("top").unwrap());
}
EOF
