        .arg(Arg::new("n").short('n').long("n").default_value("2").value_name("2|3|4|w|file").help("use bi-(2), tri-(3), tetragrams(4), (w)ords or comma separated wordlist file."))
        .arg(Arg::new("top").short('t').long("top").default_value("50").value_name("1-200").value_parser(value_parser!(i32)).help("use the top X ngrams ordered by usage."))
        .arg(Arg::new("combi").short('c').long("combi").default_value("2").value_name("1-200").value_parser(value_parser!(i32)).help("how many different ngrams to use in a single lesson."))
        .arg(Arg::new("rep").short('r').long("rep").default_value("3").value_name("number").value_parser(value_parser!(i32)).help("how often to repeat *each* different ngram in a lesson."))
        .arg(Arg::new("wpm").short('w').long("wpm").default_value("40").value_name("number").value_parser(value_parser!(i32)).help("the wpm threshold at which the lesson is considered a success."))
        .arg(Arg::new("acc").short('a').long("acc").default_value("94").value_name("0-100").value_parser(value_parser!(i32)).help("the accuracy in percent at which the lesson is considered a success."))
        .arg(Arg::new("emu-in").long("emu-in").default_value("").value_name("layout").hide_default_value(true).help("your current keyboard layout. only needed if you want to emulate a different layout. see docs for supported layouts. [default: ]"))
        .arg(Arg::new("emu-out").long("emu-out").default_value("").value_name("layout").hide_default_value(true).help("the layout you want to emulate. only needed if you want to emulate a different layout. see docs for supported layouts. [default: ]"))
        .arg(Arg::new("show-ortho").long("show-ortho").action(clap::ArgAction::SetTrue).help("show keyboard in ortholinear format"))
        .arg(Arg::new("nokb").long("nokb").action(clap::ArgAction::SetTrue).help("pass this flag to disable the keyboard layout display."))
        .arg(Arg::new("cat").long("cat").action(clap::ArgAction::SetTrue).help("the most important flag. don't practice alone."))
}

fn main() -> anyhow::Result<()> {
    let m = match cli().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            let mut s = e.to_string();
            if s.contains("tip:") {
                let lines: Vec<String> = s.lines().map(|l| l.to_string()).collect();
                let mut out_lines: Vec<String> = Vec::new();
                for line in lines {
                    if line.starts_with("Usage: ") {
                        let bin = line.split_whitespace().nth(1).unwrap_or("executable");
                        out_lines.push(format!("Usage: {} <--n <2|3|4|w|file>|--top <1-200>|--combi <1-200>|--rep <number>|--wpm <number>|--acc <0-100>|--emu-in <layout>|--emu-out <layout>|--show-ortho|--nokb|--cat>", bin));
                    } else {
                        out_lines.push(line);
                    }
                }
                s = out_lines.join("\n") + "\n";
                eprint!("{}", s);
                std::process::exit(2);
            } else {
                e.exit();
            }
        }
    };
    let top = *m.get_one::<i32>("top").unwrap();
    let combi = *m.get_one::<i32>("combi").unwrap();
    let rep = *m.get_one::<i32>("rep").unwrap();
    let wpm_thresh = *m.get_one::<i32>("wpm").unwrap();
    let acc_thresh = *m.get_one::<i32>("acc").unwrap();
    let n_str = m.get_one::<String>("n").unwrap().clone();
    let emu_in = m.get_one::<String>("emu-in").unwrap().clone();
    let emu_out = m.get_one::<String>("emu-out").unwrap().clone();
    let show_ortho = *m.get_one::<bool>("show-ortho").unwrap();
    let nokb = *m.get_one::<bool>("nokb").unwrap();
    let cat = *m.get_one::<bool>("cat").unwrap();

    if top < 1 || top > 200 {
        println!("Invalid argument for top. Use a number between 1 and 200.");
        std::process::exit(1);
    }
    if combi < 1 || combi > 200 {
        println!("Invalid argument for combi. Use a number between 1 and 200.");
        std::process::exit(1);
    }
    if rep < 1 || rep > 200 {
        println!("Invalid argument for rep. Use a number between 1 and 200.");
        std::process::exit(1);
    }
    if wpm_thresh < 1 || wpm_thresh > 200 {
        println!("Invalid argument for wpm. Use a number between 1 and 200.");
        std::process::exit(1);
    }
    if acc_thresh < 0 || acc_thresh > 100 {
        println!("Invalid argument for acc. Use a number between 0 and 100.");
        std::process::exit(1);
    }
    if (emu_in.is_empty() && !emu_out.is_empty()) || (!emu_in.is_empty() && emu_out.is_empty()) {
        println!("You need to specify both emu_in and emu_out.");
        std::process::exit(1);
    }
    let file_words: Option<Vec<String>> = if n_str != "2" && n_str != "3" && n_str != "4" && n_str != "w" {
        let path = std::path::Path::new(&n_str);
        if !path.is_file() {
            println!("File not found: {}", n_str);
            std::process::exit(1);
        }
        Some(ngrams::load_file_words(&n_str))
    } else {
        None
    };
    let pool = ngrams::get_pool(&n_str, top as usize, file_words.as_ref());

    // Determine display layout name (emu_out if emu enabled else qwerty? Actually without emu, display is qwerty)
    let display_layout = if !emu_out.is_empty() { emu_out.clone() } else { "qwerty".to_string() };

    let mut game = game::Game::new();
    let mut terminal = ratatui::init();

    // First draw with #0 (to match original two-frame behavior and empty-file panic display)
    {
        let g = &game;
        let _ = terminal.draw(|f| draw_ui(f, g, wpm_thresh, acc_thresh, &display_layout, show_ortho, nokb, cat));
    }
    // Generate first lesson (may panic for empty pool like original)
    game.next_lesson(&pool, combi as usize, rep as usize);

    loop {
        terminal.draw(|f| draw_ui(f, &game, wpm_thresh, acc_thresh, &display_layout, show_ortho, nokb, cat))?;
        // Poll with timeout to allow resize redraw? Original redraws continuously? We poll 50ms and redraw each loop (even without input) to handle resize?
        // Actually we redraw every loop iteration (every 50ms) to match original's continuous redraw? Original seems to redraw very frequently (many cursor moves in pty). Let's redraw every 50ms.
        if event::poll(Duration::from_millis(50))? {
            if let Event::Key(k) = event::read()? {
                // Quit
                if k.code == KeyCode::Esc {
                    break;
                }
                if (k.code == KeyCode::Char('c') || k.code == KeyCode::Char('C')) && k.modifiers.contains(KeyModifiers::CONTROL) {
                    break;
                }
                // Backspace (including C-h which crossterm reports as Backspace? Actually C-h might be Char('h')+CONTROL or Backspace depending on terminal.
                // Our earlier test showed C-h acts as Backspace, so crossterm must report it as Backspace. Handle Backspace.
                if k.code == KeyCode::Backspace {
                    if !game.input.is_empty() {
                        game.input.pop();
                        game.total += 1;
                        game.correct += 1; // BS counted as correct
                        if game.input.is_empty() {
                            game.start = None;
                        }
                    }
                    continue;
                }
                // Enter -> space
                let mut ch_opt: Option<char> = None;
                if k.code == KeyCode::Enter {
                    ch_opt = Some(' ');
                } else if let KeyCode::Char(c) = k.code {
                    // Ignore if control/alt held? Except we already handled Ctrl-C. For other Ctrl+char, original types the char (ignores modifiers) except C-h (which is Backspace, already handled).
                    // But what about C-h as Char('h')+CONTROL (if terminal doesn't translate)? Our test showed C-h deletes, so it must be Backspace, not Char.
                    // For safety, if CONTROL held and c=='h', treat as Backspace? Let's handle: if CONTROL and c=='h' or 'H', do backspace.
                    if k.modifiers.contains(KeyModifiers::CONTROL) && (c == 'h' || c == 'H') {
                        if !game.input.is_empty() {
                            game.input.pop();
                            game.total += 1;
                            game.correct += 1;
                            if game.input.is_empty() {
                                game.start = None;
                            }
                        }
                        continue;
                    }
                    // For other Ctrl/Alt, original still types the char (we saw C-a types 'a', M-a types 'a'). So ignore modifiers and use c.
                    ch_opt = Some(c);
                } else {
                    // Tab, Delete, arrows, F-keys, etc. ignored
                    continue;
                }
                if let Some(mut c) = ch_opt {
                    // Emu mapping (before filter? Mapping may produce punctuation which is then ignored)
                    // For emu, map c (including uppercase) via layout positions. Space stays space.
                    if !emu_in.is_empty() || !emu_out.is_empty() {
                        c = keyboard::map_char(c, &emu_in, &emu_out);
                    }
                    // Filter: only alphabetic or space accepted. (Enter already mapped to space)
                    if !(c.is_alphabetic() || c == ' ') {
                        continue;
                    }
                    // If lesson completed? Actually input length < lesson length? If already complete (should have advanced), ignore? But lesson advances immediately on completion, so input never exceeds.
                    let lesson_chars: Vec<char> = game.lesson.chars().collect();
                    if game.input.len() >= lesson_chars.len() {
                        continue;
                    }
                    // Start timer if first input
                    if game.input.is_empty() && game.start.is_none() {
                        game.start = Some(Instant::now());
                    }
                    let pos = game.input.len();
                    let expected = lesson_chars[pos];
                    game.input.push(c);
                    game.total += 1;
                    if c == expected {
                        game.correct += 1;
                    }
                    // Check completion: input length == lesson length AND all correct? Actually completion requires all correct? Let's see:
                    // Earlier we saw with 1 uncorrected error, lesson did NOT advance even though input length == lesson length. So completion requires exact match, not just length.
                    // How to check? Compare input vs lesson fully: if input == lesson_chars, then complete.
                    if game.input.len() == lesson_chars.len() {
                        let mut all_correct = true;
                        for (a, b) in game.input.iter().zip(lesson_chars.iter()) {
                            if a != b {
                                all_correct = false;
                                break;
                            }
                        }
                        if all_correct {
                            // Calculate WPM and Acc
                            let elapsed = game.start.map(|s| s.elapsed()).unwrap_or(Duration::from_millis(1));
                            let secs = elapsed.as_secs_f64();
                            // Avoid div by zero: if secs very small, WPM huge? Original with fast typing gave 800+ WPM, not infinite. With 0.4s, 300+. If secs==0 (instant), what? Probably still compute with small secs, giving huge WPM. But to avoid inf, ensure secs > 0.001?
                            let nonspace = game.lesson.chars().filter(|&ch| ch != ' ').count() as f64;
                            let words = nonspace / 5.0;
                            let minutes = secs / 60.0;
                            let wpm_val = if minutes > 0.0 { (words / minutes) as usize } else { 0 };
                            let acc_val = if game.total > 0 { (game.correct * 100 / game.total) as usize } else { 100 };
                            game.wpms.push(wpm_val);
                            game.accs.push(acc_val);
                            if wpm_val as i32 >= wpm_thresh && acc_val as i32 >= acc_thresh {
                                game.good += 1;
                            } else {
                                game.bad += 1;
                            }
                            // Next lesson
                            game.next_lesson(&pool, combi as usize, rep as usize);
                        } else {
                            // Not all correct, stay (do nothing, wait for backspaces to fix)
                            // Note: input stays full length, further inputs ignored until backspace (since len==lesson len)
                        }
                    }
                }
            }
        }
        // else timeout: just loop to redraw (for resize handling)
    }
    ratatui::restore();
    Ok(())
}

fn draw_ui(f: &mut ratatui::Frame, game: &game::Game, wpm_thresh: i32, acc_thresh: i32, display_layout: &str, show_ortho: bool, nokb: bool, cat: bool) {
    let area = f.area();
    let need_h: u16 = if nokb { 13 } else { 20 };
    if area.width < 79 || area.height < need_h {
        // Resize message centered at top
        let mut lines: Vec<Line> = Vec::new();
        if nokb {
            lines.push(Line::from("Please resize your terminal to at least 80x13.").centered());
            lines.push(Line::from("<esc> or <ctrl-c> to quit").centered());
        } else {
            lines.push(Line::from("Please resize your terminal to at least 80x20,").centered());
            lines.push(Line::from("or consider disabling the keyboard display with --nokb").centered());
            lines.push(Line::from(""));
            lines.push(Line::from("<esc> or <ctrl-c> to quit").centered());
        }
        let p = Paragraph::new(lines);
        f.render_widget(p, area);
        return;
    }
    let h: u16 = if nokb { 13 } else { 19 };
    let outer_area = Rect::new(0, 0, 79.min(area.width), h.min(area.height));
    let title = Line::from(vec![
        Span::raw(" Quit "),
        Span::styled("<esc> ", Style::new().bold().fg(Color::Indexed(4))),
    ]).right_aligned();
    let block = Block::new().borders(Borders::ALL).border_type(BorderType::Rounded).title_top(title);
    // Render outer block as background? We need inner area for content. Use block.inner()?
    // Instead, render block first, then content in inner rects.
    f.render_widget(block, outer_area);
    // Title line y=1
    let title_line = Line::from(vec![
        Span::styled("               ngrrram!", Style::new().bold()),
        Span::styled("   by winterveil", Style::new().italic().fg(Color::Indexed(7))),
    ]).centered();
    f.render_widget(Paragraph::new(title_line), Rect::new(1, 1, 77, 1));
    // Sep y=2
    f.render_widget(Paragraph::new(Line::from("─".repeat(77))), Rect::new(1, 2, 77, 1));
    // Lesson line y=3
    {
        let left = format!("    Lesson #{}", game.lesson_num);
        let right = format!("✔: {}, ✘: {}    ", game.good, game.bad);
        // left len + middle + right len =77. Need to handle unicode width? ✔/✘ are width 1? In terminal, they are 1? Assume 1.
        // Compute display width: left.chars().count() + right.chars().count()? For ascii, same as len, but for ✔/✘ (3 bytes utf8, 1 char), need chars count.
        let left_w = left.chars().count();
        let right_w = right.chars().count();
        let mid = if 77 >= left_w + right_w { 77 - left_w - right_w } else { 0 };
        let line = Line::from(vec![
            Span::raw(left),
            Span::raw(" ".repeat(mid)),
            Span::styled(format!("✔: {}, ", game.good), Style::new().fg(Color::Indexed(2))),
            Span::styled(format!("✘: {}    ", game.bad), Style::new().fg(Color::Indexed(1))),
        ]);
        f.render_widget(Paragraph::new(line), Rect::new(1, 3, 77, 1));
    }
    // Sep y=4
    f.render_widget(Paragraph::new(Line::from("─".repeat(77))), Rect::new(1, 4, 77, 1));
    // Empty y=5 (nothing)
    // Lesson text y=6, error y=7
    {
        let lesson = &game.lesson;
        let input = &game.input;
        // Build lesson spans with colors
        // Lesson may be empty (for #0 first draw) -> render empty centered? Original first frame shows empty lesson lines (blank). Our centered empty will be blank. Good.
        if lesson.is_empty() {
            // Render empty (blank) - nothing? But need to ensure row is blank (outer block background). We can render empty paragraph.
            f.render_widget(Paragraph::new(Line::from("").centered()), Rect::new(1, 6, 77, 1));
            f.render_widget(Paragraph::new(Line::from("").centered()), Rect::new(1, 7, 77, 1));
        } else {
            let lesson_chars: Vec<char> = lesson.chars().collect();
            // Build lesson line spans: runs of same style merged
            // Styles: bold + green for correct, bold + red for wrong (with • for space), bold for untyped
            let mut spans: Vec<Span> = Vec::new();
            // We need to handle runs: iterate over lesson_chars with index, determine style for typed part, group contiguous same style
            // For untyped suffix, single span with bold (no fg)
            // For typed prefix, group by correct/wrong
            let mut i = 0;
            while i < lesson_chars.len() {
                if i < input.len() {
                    // typed: check correct?
                    let is_correct = input[i] == lesson_chars[i];
                    // Find run end with same correctness
                    let mut j = i + 1;
                    while j < lesson_chars.len() && j < input.len() && (input[j] == lesson_chars[j]) == is_correct {
                        j += 1;
                    }
                    // Build text for i..j, replacing space with • if wrong and expected is space
                    let mut s = String::new();
                    for k in i..j {
                        let ec = lesson_chars[k];
                        if !is_correct && ec == ' ' {
                            s.push('•');
                        } else {
                            s.push(ec);
                        }
                    }
                    let style = if is_correct {
                        Style::new().bold().fg(Color::Indexed(2))
                    } else {
                        Style::new().bold().fg(Color::Indexed(1))
                    };
                    spans.push(Span::styled(s, style));
                    i = j;
                } else {
                    // untyped suffix: from i to end as one span bold
                    let s: String = lesson_chars[i..].iter().collect();
                    spans.push(Span::styled(s, Style::new().bold()));
                    break;
                }
            }
            // If lesson empty? Already handled. If input empty, spans will be single bold suffix (entire lesson). Good.
            // Edge: if input len == lesson len and all correct? But then lesson would have advanced, input cleared. So this state (full correct) never rendered (since advance immediate). Good.
            // If input len == lesson len with errors, spans cover all typed (no suffix). Good.
            let line = Line::from(spans).centered();
            // Need bold for whole line? Our spans already have bold. But original has \x1b[1m for whole line plus colors. Our spans with bold each will produce same? Ratatui will emit bold for each span. For suffix (bold only), it will emit \x1b[1m...\x1b[22m? Original shows \x1b[1m...\x1b[0m for whole line. Slight difference in reset codes (\x1b[22m vs \x1b[0m)? But tmux capture with -e shows \x1b[1m...\x1b[0m? Our earlier capture for lesson showed \x1b[1m...\x1b[0m. Ratatui's rendering for bold spans may produce \x1b[1m...\x1b[22m (bold off) vs \x1b[0m (reset)? Need to check what our code produces vs original. Our title already matched (\x1b[1m...\x1b[0;3m...), so ratatui's reset handling matches original (since we used same ratatui version and similar spans). Good. For lesson, our spans should produce similar to original (with \x1b[1m and \x1b[38;5;...). Let's trust.
            f.render_widget(Paragraph::new(line), Rect::new(1, 6, 77, 1));
            // Error line: for each position, if typed and wrong, show typed char, else space. All italic grey.
            {
                let mut err_str = String::new();
                for idx in 0..lesson_chars.len() {
                    if idx < input.len() {
                        if input[idx] != lesson_chars[idx] {
                            // Show typed char. For space/Enter (space) wrong, show space (invisible). For normal, show char.
                            err_str.push(input[idx]);
                        } else {
                            err_str.push(' ');
                        }
                    } else {
                        err_str.push(' ');
                    }
                }
                let err_line = Line::from(Span::styled(err_str, Style::new().italic().fg(Color::Indexed(7)))).centered();
                f.render_widget(Paragraph::new(err_line), Rect::new(1, 7, 77, 1));
            }
        }
    }
    // Keyboard or empty
    if nokb {
        // Empty row y=8, Sep y=9, stats y=10,11
        // y=8 empty (nothing)
        f.render_widget(Paragraph::new(Line::from("─".repeat(77))), Rect::new(1, 9, 77, 1));
        // Stats with possible cat
        draw_stats(f, game, wpm_thresh, acc_thresh, cat, true);
    } else {
        // Keyboard rows y=8..14 (7 rows)
        draw_keyboard(f, display_layout, show_ortho, cat);
        // Sep y=15 (or with cat, sep has cat art? Actually with cat, sep line y=15 has "/▔▔...\" art overlapping? Let's handle in draw_keyboard or draw_stats?)
        // For cat with kb, sep line y=15 is "────────────────────────────────────────────────────────────/▔▔▔▔▔▔▔▔||▔▔\───" (with cat table). For non-cat, plain dashes.
        if cat {
            // Custom sep with cat table
            let sep_cat = "────────────────────────────────────────────────────────────/▔▔▔▔▔▔▔▔||▔▔\\───";
            f.render_widget(Paragraph::new(Line::from(sep_cat)), Rect::new(1, 15, 77, 1));
        } else {
            f.render_widget(Paragraph::new(Line::from("─".repeat(77))), Rect::new(1, 15, 77, 1));
        }
        draw_stats(f, game, wpm_thresh, acc_thresh, cat, false);
    }
}

