        }
        Some(ngrams::load_file_words(&n_str))
    } else {
        None
    };
    let pool = ngrams::get_pool(&n_str, top as usize, file_words.as_ref());

    // Determine display layout name (emu_out if emu enabled else qwerty? Actually without emu, display is qwerty)
    let display_layout = if !emu_out.is_empty() { emu_out.clone() } else { "qwerty".to_string() };

    let mut game = game::Game::new();
    let mut terminal = ratatui::init();

    // First draw with #0 (to match original two-frame behavior and empty-file panic display)
    {
        let g = &game;
        let _ = terminal.draw(|f| draw_ui(f, g, wpm_thresh, acc_thresh, &display_layout, show_ortho, nokb, cat));
    }
    // Generate first lesson (may panic for empty pool like original)
    game.next_lesson(&pool, combi as usize, rep as usize);

    loop {
        terminal.draw(|f| draw_ui(f, &game, wpm_thresh, acc_thresh, &display_layout, show_ortho, nokb, cat))?;
        // Poll with timeout to allow resize redraw? Original redraws continuously? We poll 50ms and redraw each loop (even without input) to handle resize?
        // Actually we redraw every loop iteration (every 50ms) to match original's continuous redraw? Original seems to redraw very frequently (many cursor moves in pty). Let's redraw every 50ms.
        if event::poll(Duration::from_millis(50))? {
            if let Event::Key(k) = event::read()? {
                // Quit
                if k.code == KeyCode::Esc {
                    break;
                }
                if (k.code == KeyCode::Char('c') || k.code == KeyCode::Char('C')) && k.modifiers.contains(KeyModifiers::CONTROL) {
                    break;
                }
                // Backspace (including C-h which crossterm reports as Backspace? Actually C-h might be Char('h')+CONTROL or Backspace depending on terminal.
                // Our earlier test showed C-h acts as Backspace, so crossterm must report it as Backspace. Handle Backspace.
                if k.code == KeyCode::Backspace {
                    if !game.input.is_empty() {
