                    if !(c.is_alphabetic() || c == ' ') {
                        continue;
                    }
                    // If lesson completed? Actually input length < lesson length? If already complete (should have advanced), ignore? But lesson advances immediately on completion, so input never exceeds.
                    let lesson_chars: Vec<char> = game.lesson.chars().collect();
                    if game.input.len() >= lesson_chars.len() {
