}

fn draw_ui(f: &mut ratatui::Frame, game: &game::Game, wpm_thresh: i32, acc_thresh: i32, display_layout: &str, show_ortho: bool, nokb: bool, cat: bool) {
    let area = f.area();
    let need_h: u16 = if nokb { 13 } else { 20 };
    if area.width < 79 || area.height < need_h {
        // Resize message centered at top
        let mut lines: Vec<Line> = Vec::new();
        if nokb {
            lines.push(Line::from("Please resize your terminal to at least 80x13.").centered());
            lines.push(Line::from("<esc> or <ctrl-c> to quit").centered());
        } else {
            lines.push(Line::from("Please resize your terminal to at least 80x20,").centered());
            lines.push(Line::from("or consider disabling the keyboard display with --nokb").centered());
            lines.push(Line::from(""));
            lines.push(Line::from("<esc> or <ctrl-c> to quit").centered());
        }
        let p = Paragraph::new(lines);
        f.render_widget(p, area);
        return;
    }
    let h: u16 = if nokb { 13 } else { 19 };
    let outer_area = Rect::new(0, 0, 79.min(area.width), h.min(area.height));
    let title = Line::from(vec![
        Span::raw(" Quit "),
        Span::styled("<esc> ", Style::new().bold().fg(Color::Indexed(4))),
    ]).right_aligned();
    let block = Block::new().borders(Borders::ALL).border_type(BorderType::Rounded).title_top(title);
    // Render outer block as background? We need inner area for content. Use block.inner()?
    // Instead, render block first, then content in inner rects.
    f.render_widget(block, outer_area);
    // Title line y=1
    let title_line = Line::from(vec![
        Span::styled("               ngrrram!", Style::new().bold()),
        Span::styled("   by winterveil", Style::new().italic().fg(Color::Indexed(7))),
    ]).centered();
    f.render_widget(Paragraph::new(title_line), Rect::new(1, 1, 77, 1));
    // Sep y=2
    f.render_widget(Paragraph::new(Line::from("─".repeat(77))), Rect::new(1, 2, 77, 1));
    // Lesson line y=3
    {
        let left = format!("    Lesson #{}", game.lesson_num);
        let right = format!("✔: {}, ✘: {}    ", game.good, game.bad);
        // left len + middle + right len =77. Need to handle unicode width? ✔/✘ are width 1? In terminal, they are 1? Assume 1.
        // Compute display width: left.chars().count() + right.chars().count()? For ascii, same as len, but for ✔/✘ (3 bytes utf8, 1 char), need chars count.
        let left_w = left.chars().count();
        let right_w = right.chars().count();
        let mid = if 77 >= left_w + right_w { 77 - left_w - right_w } else { 0 };
        let line = Line::from(vec![
            Span::raw(left),
            Span::raw(" ".repeat(mid)),
            Span::styled(format!("✔: {}, ", game.good), Style::new().fg(Color::Indexed(2))),
            Span::styled(format!("✘: {}    ", game.bad), Style::new().fg(Color::Indexed(1))),
        ]);
        f.render_widget(Paragraph::new(line), Rect::new(1, 3, 77, 1));
    }
    // Sep y=4
    f.render_widget(Paragraph::new(Line::from("─".repeat(77))), Rect::new(1, 4, 77, 1));
    // Empty y=5 (nothing)
    // Lesson text y=6, error y=7
    {
        let lesson = &game.lesson;
        let input = &game.input;
        // Build lesson spans with colors
        // Lesson may be empty (for #0 first draw) -> render empty centered? Original first frame shows empty lesson lines (blank). Our centered empty will be blank. Good.
        if lesson.is_empty() {
            // Render empty (blank) - nothing? But need to ensure row is blank (outer block background). We can render empty paragraph.
            f.render_widget(Paragraph::new(Line::from("").centered()), Rect::new(1, 6, 77, 1));
            f.render_widget(Paragraph::new(Line::from("").centered()), Rect::new(1, 7, 77, 1));
        } else {
            let lesson_chars: Vec<char> = lesson.chars().collect();
            // Build lesson line spans: runs of same style merged
            // Styles: bold + green for correct, bold + red for wrong (with • for space), bold for untyped
            let mut spans: Vec<Span> = Vec::new();
            // We need to handle runs: iterate over lesson_chars with index, determine style for typed part, group contiguous same style
            // For untyped suffix, single span with bold (no fg)
            // For typed prefix, group by correct/wrong
            let mut i = 0;
            while i < lesson_chars.len() {
                if i < input.len() {
                    // typed: check correct?
                    let is_correct = input[i] == lesson_chars[i];
                    // Find run end with same correctness
                    let mut j = i + 1;
                    while j < lesson_chars.len() && j < input.len() && (input[j] == lesson_chars[j]) == is_correct {
                        j += 1;
                    }
                    // Build text for i..j, replacing space with • if wrong and expected is space
                    let mut s = String::new();
                    for k in i..j {
                        let ec = lesson_chars[k];
                        if !is_correct && ec == ' ' {
                            s.push('•');
                        } else {
                            s.push(ec);
                        }
                    }
                    let style = if is_correct {
                        Style::new().bold().fg(Color::Indexed(2))
                    } else {
                        Style::new().bold().fg(Color::Indexed(1))
                    };
                    spans.push(Span::styled(s, style));
                    i = j;
                } else {
                    // untyped suffix: from i to end as one span bold
                    let s: String = lesson_chars[i..].iter().collect();
                    spans.push(Span::styled(s, Style::new().bold()));
                    break;
                }
            }
            // If lesson empty? Already handled. If input empty, spans will be single bold suffix (entire lesson). Good.
            // Edge: if input len == lesson len and all correct? But then lesson would have advanced, input cleared. So this state (full correct) never rendered (since advance immediate). Good.
            // If input len == lesson len with errors, spans cover all typed (no suffix). Good.
            let line = Line::from(spans).centered();
            // Need bold for whole line? Our spans already have bold. But original has \x1b[1m for whole line plus colors. Our spans with bold each will produce same? Ratatui will emit bold for each span. For suffix (bold only), it will emit \x1b[1m...\x1b[22m? Original shows \x1b[1m...\x1b[0m for whole line. Slight difference in reset codes (\x1b[22m vs \x1b[0m)? But tmux capture with -e shows \x1b[1m...\x1b[0m? Our earlier capture for lesson showed \x1b[1m...\x1b[0m. Ratatui's rendering for bold spans may produce \x1b[1m...\x1b[22m (bold off) vs \x1b[0m (reset)? Need to check what our code produces vs original. Our title already matched (\x1b[1m...\x1b[0;3m...), so ratatui's reset handling matches original (since we used same ratatui version and similar spans). Good. For lesson, our spans should produce similar to original (with \x1b[1m and \x1b[38;5;...). Let's trust.
            f.render_widget(Paragraph::new(line), Rect::new(1, 6, 77, 1));
            // Error line: for each position, if typed and wrong, show typed char, else space. All italic grey.
            {
                let mut err_str = String::new();
                for idx in 0..lesson_chars.len() {
                    if idx < input.len() {
                        if input[idx] != lesson_chars[idx] {
                            // Show typed char. For space/Enter (space) wrong, show space (invisible). For normal, show char.
                            err_str.push(input[idx]);
                        } else {
                            err_str.push(' ');
                        }
                    } else {
                        err_str.push(' ');
                    }
                }
                let err_line = Line::from(Span::styled(err_str, Style::new().italic().fg(Color::Indexed(7)))).centered();
                f.render_widget(Paragraph::new(err_line), Rect::new(1, 7, 77, 1));
            }
        }
    }
    // Keyboard or empty
    if nokb {
        // Empty row y=8, Sep y=9, stats y=10,11
        // y=8 empty (nothing)
        f.render_widget(Paragraph::new(Line::from("─".repeat(77))), Rect::new(1, 9, 77, 1));
        // Stats with possible cat
        draw_stats(f, game, wpm_thresh, acc_thresh, cat, true);
    } else {
        // Keyboard rows y=8..14 (7 rows)
        draw_keyboard(f, display_layout, show_ortho, cat);
        // Sep y=15 (or with cat, sep has cat art? Actually with cat, sep line y=15 has "/▔▔...\" art overlapping? Let's handle in draw_keyboard or draw_stats?)
        // For cat with kb, sep line y=15 is "────────────────────────────────────────────────────────────/▔▔▔▔▔▔▔▔||▔▔\───" (with cat table). For non-cat, plain dashes.
        if cat {
            // Custom sep with cat table
            let sep_cat = "────────────────────────────────────────────────────────────/▔▔▔▔▔▔▔▔||▔▔\\───";
            f.render_widget(Paragraph::new(Line::from(sep_cat)), Rect::new(1, 15, 77, 1));
        } else {
            f.render_widget(Paragraph::new(Line::from("─".repeat(77))), Rect::new(1, 15, 77, 1));
        }
        draw_stats(f, game, wpm_thresh, acc_thresh, cat, false);
    }
}

fn draw_stats(f: &mut ratatui::Frame, game: &game::Game, wpm_thresh: i32, acc_thresh: i32, cat: bool, nokb: bool) {
