    elif ch == "BS": subprocess.run(["tmux", "send-keys", "-t", sess, "BSpace"], capture_output=True)
    else: subprocess.run(["tmux", "send-keys", "-t", sess, "-l", ch], capture_output=True)
    tm.sleep(delay)

